/* Delivery requirement and storyboard editors. Editing uses a detached draft until confirmation. */
window.createRequirementEditor=function(ctx){
 const {task,products,product,production:p,company:c,esc,icon,btn,openModal,closeModal,persist,render,toast}=ctx;
 const $=s=>document.querySelector(s);let rows=null,taskId=null,revision=0,shots=null,shotTarget=null,shotContext=null;
 const select=(label,field,values,value)=>`<label class="company-field"><span>${label}</span><select data-plan-field="${field}">${values.map(v=>`<option value="${esc(v[0])}" ${String(value)===String(v[0])?'selected':''}>${esc(v[1])}</option>`).join('')}</select></label>`;
 const planInput=(label,field,value,type='text',extra='')=>`<label class="company-field"><span>${label}</span><input data-plan-field="${field}" type="${type}" value="${esc(value)}" ${extra}></label>`;
 function capture(){for(const el of document.querySelectorAll('[data-plan-row]')){const r=rows[+el.dataset.planRow];for(const field of el.querySelectorAll('[data-plan-field]'))r[field.dataset.planField]=['count','duration'].includes(field.dataset.planField)?Number(field.value):field.value;}}
 function openPlan(){c.requireRight('create');rows=p.copy(p.ensure(task()));taskId=task().id;revision=task().planRevision||0;showPlan();}
 function showPlan(error=''){openModal('配置交付要求',`<p class="company-form-intro">按商品定义模块、数量与规格。每一张图片或视频单独采用，保留仍匹配的采用版本。</p><div class="requirement-editor-list">${rows.map((r,i)=>`<article class="requirement-editor-row" data-plan-row="${i}"><div class="between"><strong>要求 ${String(i+1).padStart(2,'0')}</strong><button class="text-button" data-action="requirements-remove" data-id="${i}">移除</button></div><div class="company-form-grid">${select('商品','product',task().products.map(pid=>[pid,product(pid).name]),r.product)}${select('用途','purpose',[['main','商品主图'],['detail','详情素材'],['video','带货视频']],r.purpose)}${planInput('模块名称','module',r.module,'text','maxlength="40"')}${planInput('数量','count',r.count,'number','min="1" max="6" step="1"')}${select('画面比例','ratio',['1:1','3:4','9:16','16:9'].map(x=>[x,x]),r.ratio)}${select('清晰度','quality',(r.purpose==='video'?['1080P']:['1024 × 1024','2048 × 2048','4096 × 4096']).map(x=>[x,x]),r.quality)}${r.purpose==='video'?select('视频总时长','duration',[6,12,15].map(x=>[x,x+' 秒']),r.duration):''}</div></article>`).join('')}</div><div class="requirement-add-actions">${[['main','主图'],['detail','详情模块'],['video','视频']].map(([id,name])=>`<button class="btn sm" data-action="requirements-add" data-id="${id}">${icon('plus')}${name}</button>`).join('')}</div><div class="field-error" id="requirements-error" role="alert">${esc(error)}</div>`,btn('取消','close-modal')+btn('核对并保存','requirements-preview','primary'),{wide:true});$('.overlay .modal').classList.add('company-editor');}
 function captureShots(){for(const el of document.querySelectorAll('[data-shot-row]')){const s=shots[+el.dataset.shotRow];for(const field of el.querySelectorAll('[data-shot-field]'))s[field.dataset.shotField]=field.dataset.shotField==='duration'?Number(field.value):field.value;}}
 function openShots(target,back=''){c.requireRight('create');const d=ctx.getDraft(target);if(!d||d.media!=='video')throw new Error('请选择有效视频草稿。');shotTarget=target;shotContext={taskId:task().id,signature:p.signature(d),back};shots=p.copy(d.shots||p.defaultShots(d));showShots();}
 function showShots(error=''){const d=ctx.getDraft(shotTarget);openModal('编辑视频分镜',`<p class="company-form-intro">${esc(product(d.product).name)} · 目标 ${d.duration} 秒。画面和文案以已确认事实为依据，镜头时长总和须匹配。</p><div class="storyboard-editor-list">${shots.map((s,i)=>`<article class="storyboard-editor-row" data-shot-row="${i}"><div class="between"><strong>镜头 ${String(i+1).padStart(2,'0')}</strong><button class="text-button" data-action="shots-remove" data-id="${i}">移除</button></div><label class="company-field"><span>时长（秒）</span><input data-shot-field="duration" aria-label="镜头 ${i+1} 时长" type="number" min="1" step="1" value="${s.duration}"></label><label class="company-field"><span>画面 / 动作 / 运镜</span><textarea data-shot-field="visual" aria-label="镜头 ${i+1} 画面" maxlength="500">${esc(s.visual)}</textarea></label><label class="company-field"><span>字幕 / 文案（选填）</span><input data-shot-field="copy" aria-label="镜头 ${i+1} 文案" maxlength="200" value="${esc(s.copy||'')}"></label></article>`).join('')}</div><div class="between"><button class="btn sm" data-action="shots-add" ${shots.length>=12?'disabled':''}>${icon('plus')}添加镜头</button><span id="shots-total" role="status">已编排 ${shots.reduce((n,s)=>n+ +s.duration,0)} / ${d.duration} 秒</span></div><label class="checkbox-label"><input id="shots-facts-confirmed" type="checkbox">已核对画面、文案与当前商品事实</label><div class="field-error" id="shots-error" role="alert">${esc(error)}</div>`,btn('取消','close-modal')+btn('保存并确认分镜','shots-save','primary'),{wide:true});$('.overlay .modal').classList.add('company-editor');}
 function summary(d){if(d.purpose==='clip')return '<p class="case-preview-note">单段视频片段 · 静态关键帧示例；未要求完整分镜，不计入带货成片交付。</p>';const shots=d.shots||p.defaultShots(d);let at=0;return `<div class="editable-shot-summary">${shots.map((s,i)=>{const start=at;at+=+s.duration;return `<div><strong>${String(i+1).padStart(2,'0')} · ${start}–${at}s</strong><p>${esc(s.visual)}</p>${s.copy?`<small>${esc(s.copy)}</small>`:''}</div>`;}).join('')}</div>`;}
 function action(action,id){if(!action.startsWith('requirements-')&&!action.startsWith('shots-'))return false;try{c.requireRight('create');switch(action){
  case 'requirements-open':openPlan();break;
  case 'requirements-add':capture();{const r=p.requirement(task().products[0],id);if(rows.some(x=>x.product===r.product&&x.purpose===id&&x.module===r.module))r.module+=(rows.filter(x=>x.product===r.product&&x.purpose===id).length+1);rows.push(r);}showPlan();break;
  case 'requirements-remove':capture();rows.splice(+id,1);showPlan();break;
  case 'requirements-preview':capture();{const problem=p.validatePlan(rows,task());if(problem){$('#requirements-error').textContent=problem;break;}const tmp=p.copy(task());const removed=p.savePlan(tmp,rows);openModal('确认交付要求',`<p>本次共 ${rows.length} 项要求、${rows.reduce((n,r)=>n+ +r.count,0)} 个交付位置。</p><p class="company-form-intro">${removed?`${removed} 个采用位置因规格、模块或数量变化将被清除。`:'仍匹配的采用版本全部保留。'}已生成文件、历史版本与审核决定保留。</p>`,btn('返回修改','requirements-back')+btn('确认保存','requirements-save','primary'));}break;
  case 'requirements-back':showPlan();break;
  case 'requirements-save':if(taskId!==task().id||(task().planRevision||0)!==revision)throw new Error('交付要求已变化，请重新打开配置。');{const n=p.savePlan(task(),rows);task().planRevision=revision+1;c.audit('修改交付要求',task().id,`${rows.length} 项要求；移除 ${n} 个失配采用`);persist();closeModal();render();toast('交付要求已保存，采用与缺口已重新核对。');}break;
  case 'shots-edit':openShots(id,ctx.getDraft(id)===task().draft?'generation':'');break;
  case 'shots-add':captureShots();if(shots.length<12)shots.push({duration:1,visual:'',copy:''});showShots();break;
  case 'shots-remove':captureShots();shots.splice(+id,1);showShots();break;
  case 'shots-save':captureShots();{const d=ctx.getDraft(shotTarget);if(task().id!==shotContext.taskId||!d||p.signature(d)!==shotContext.signature)throw new Error('视频输入已变化，请重新打开分镜。');const problem=p.validateShots(d,shots);if(problem){$('#shots-error').textContent=problem;break;}if(!$('#shots-facts-confirmed').checked){$('#shots-error').textContent='请先核对商品事实。';break;}d.shots=p.copy(shots);p.confirm(d);ctx.saveShots(shotTarget);persist();closeModal();render();if(shotContext.back==='generation')ctx.showGeneration();else toast('分镜已确认；修改输入后需重新确认。');}break;
 }}catch(e){const field=$('#shots-error')||$('#requirements-error');if(field)field.textContent=e.message;else toast(e.message);}return true;}
 function input(el){if(el.dataset.shotField){captureShots();$('#shots-facts-confirmed').checked=false;$('#shots-total').textContent=`已编排 ${shots.reduce((n,s)=>n+ +s.duration,0)} / ${ctx.getDraft(shotTarget).duration} 秒`;return true;}return !!el.dataset.planField;}
 function change(el){if(el.dataset.planField==='purpose'){capture();const r=rows[+el.closest('[data-plan-row]').dataset.planRow];r.module={main:'商品主图',detail:'详情素材',video:'带货视频'}[r.purpose];r.quality=r.purpose==='video'?'1080P':'2048 × 2048';r.ratio=r.purpose==='video'?'9:16':'1:1';showPlan();return true;}return !!el.dataset.planField||!!el.dataset.shotField;}
 return{action,input,change,openPlan,openShots,summary};
};
